<script setup lang="ts">
import {computed,onMounted,ref} from 'vue'
import {useRoute} from 'vue-router'
import {WorkforceApiError} from '../api'
import {usePayrollPage} from '../payrollPage'
import {allowedPayrollActions,chooseCompany,copy} from '../payrollUi'
import {hours} from '../time'
import type {PayrollHomeData,BatchDetail,BatchAction} from '../payrollTypes'
import PayrollWorkbench from '../components/PayrollWorkbench.vue'
import {usePayrollProgressText} from '../payrollProgressText'
import PhaseStatus from '../components/PhaseStatus.vue'
const id=String(useRoute().params.id),{api,r,issue,t,p,base,home,current,loading,busy,failure,notice,load,write}=usePayrollPage(),data=ref<BatchDetail|null>(null),scope=ref<PayrollHomeData|null>(null),note=ref(''),pending=ref<{id:string;body:{expectedVersion:number;action:BatchAction;note:string}}|null>(null)
const g=usePayrollProgressText()
const actions=computed(()=>data.value?allowedPayrollActions(data.value,scope.value?.employeeId||null):[]),editable=computed(()=>data.value&&['draft','calculated'].includes(data.value.batch.status)),own=computed(()=>!!scope.value?.employeeId&&data.value?.employees.some(e=>e.id===scope.value!.employeeId))
function refresh(){if(pending.value)return;void load(async()=>{const h=await api().get<PayrollHomeData>('/payroll-home');chooseCompany(h,'');const d=await api().get<BatchDetail>('/payroll-batches/'+id);chooseCompany(h,d.batch.companyId);return {h,d}},v=>{scope.value=v.h;data.value=v.d})}
function action(a:BatchAction){if(busy.value||pending.value||!data.value||!(a==='calculate_full'?editable.value:actions.value.includes(a)))return;if(!note.value.trim()||note.value.length>500){failure.value=r('invalid');return}pending.value={id:crypto.randomUUID(),body:{expectedVersion:data.value.batch.version,action:a,note:note.value.trim()}};recover()}
function recover(){if(busy.value||!pending.value)return;const command=copy(pending.value);void write(async()=>{try{await api().put('/payroll-batches/'+id+'/actions/'+command.id,command.body);if(current())pending.value=null}catch(e){if(current()&&e instanceof WorkforceApiError&&e.status>=400&&e.status<500)pending.value=null;throw e}},refresh)}
function name(employeeId:string){return data.value?.employees.find(e=>e.id===employeeId)?.name||'—'}
onMounted(refresh)
</script>
<template><section class="wf-panel"><header class="wf-toolbar"><h2>{{r('batchDetail')}}</h2><button :disabled="loading||busy||!!pending" @click="refresh">{{t('refresh')}}</button></header><PhaseStatus :failure="failure" :notice="notice" :loading="loading"/><template v-if="data&&!loading"><dl class="wf-details"><dt>{{r('company')}}</dt><dd>{{data.batch.companyName}}</dd><dt>{{r('month')}}</dt><dd>{{data.batch.month}}</dd><dt>{{t('status')}}</dt><dd><span class="wf-badge">{{r(data.batch.status)}}</span></dd><dt>{{r('gross')}}</dt><dd>SGD {{data.batch.totalGross||'—'}}</dd><dt>{{r('net')}}</dt><dd>SGD {{data.batch.totalNet||'—'}}</dd><dt>{{r('employerCpf')}}</dt><dd>{{data.batch.totalEmployerCpf||'—'}}</dd><dt>{{r('sdl')}}</dt><dd>{{data.batch.totalSdl||'—'}}</dd><dt>{{r('employerCost')}}</dt><dd>{{data.batch.totalEmployerCost||'—'}}</dd></dl><PayrollWorkbench :company-id="data.batch.companyId" :month="data.batch.month" :batch-id="data.batch.id" :version="data.batch.version"/><p v-if="data.calculation" class="wf-hint">{{r('calculationPolicy')}} <template v-if="data.calculation.statutoryPolicy">{{data.calculation.statutoryPolicy.name}} v{{data.calculation.statutoryPolicy.version}} · {{r('policyEffectiveRange')}} {{data.calculation.statutoryPolicy.effectiveFrom}} – {{data.calculation.statutoryPolicy.effectiveTo||r('policyOpenEnd')}} <RouterLink v-if="home?.headOffice" :to="{path:base+'/statutory-policies',query:{policyId:data.calculation.statutoryPolicy.id}}">{{r('viewPolicy')}}</RouterLink></template><template v-else>{{data.calculation.policyVersion}}</template></p><p v-if="data.sourceChanged" class="wf-error">{{r('sourceChanged')}}</p><p class="wf-hint">{{r('frozenHint')}} {{r('sdlHint')}}</p><p v-if="own" class="wf-hint">{{r('ownHint')}}</p><div v-if="data.calculation?.issues.length" class="wf-issue"><strong>{{r('issues')}}</strong><ul><li v-for="(code,i) in data.calculation.issues" :key="i">{{issue(code.split(':')[0]!)}}</li></ul></div><div class="wf-table-wrap"><table><thead><tr><th>{{r('employee')}}</th><th>{{r('gross')}}</th><th>{{r('employeeCpf')}}</th><th>{{r('net')}}</th><th>{{r('issues')}}</th><th></th></tr></thead><tbody><tr v-for="e in data.employees" :key="e.id"><td>{{e.name}}</td><td>{{data.calculation?.lines.find(l=>l.employeeId===e.id)?.grossPay||'—'}}</td><td>{{data.calculation?.lines.find(l=>l.employeeId===e.id)?.employeeCpf||'—'}}</td><td>{{data.calculation?.lines.find(l=>l.employeeId===e.id)?.netPay||'—'}}</td><td class="wf-wrap-text"><div v-for="(code,i) in data.calculation?.lines.find(l=>l.employeeId===e.id)?.issues||[]" :key="i" class="wf-issue">{{issue(code)}}</div></td><td><div class="wf-inline"><RouterLink v-if="editable&&!pending" :to="base+'/payroll-batches/'+id+'/inputs/'+e.id">{{r('inputs')}}</RouterLink><RouterLink v-if="data.calculation" :to="base+'/payroll-batches/'+id+'/payslips/'+e.id">{{r('preview')}}</RouterLink><RouterLink v-if="data.batch.status==='published'&&scope?.employeeId!==e.id" :to="{path:base+'/payroll-batches/'+id+'/payments/new',query:{employeeId:e.id}}">{{r('payment')}}</RouterLink></div></td></tr><tr v-if="!data.employees.length"><td colspan="6" class="wf-empty">{{t('empty')}}</td></tr></tbody></table></div><template v-if="actions.length||editable"><label class="wf-section">{{r('note')}}<textarea v-model="note" rows="3" maxlength="500" required :disabled="busy||!!pending"></textarea></label><p class="wf-hint">{{r('voidHint')}}</p><div class="wf-inline"><button v-if="editable" :disabled="busy||!!pending||!note.trim()" @click="action('calculate_full')">{{g('full')}}</button><button v-for="a in actions" :key="a" :class="{primary:a!=='void'}" :disabled="busy||!!pending||!note.trim()" @click="action(a)">{{a==='calculate_full'?g('full'):r(a)}}</button></div></template><div v-if="pending" class="wf-section"><p class="wf-issue">{{r('recovery')}}</p><button :disabled="busy" @click="recover">{{r('recover')}}</button></div><h2 class="wf-section">{{r('paymentHistory')}}</h2><div class="wf-table-wrap"><table><thead><tr><th>{{r('employee')}}</th><th>{{r('paymentDate')}}</th><th>{{r('amount')}}</th><th>{{r('method')}}</th><th>{{r('bankName')}}</th><th>{{r('reference')}}</th><th></th></tr></thead><tbody><tr v-for="v in data.payments" :key="v.id"><td>{{name(v.employeeId)}}</td><td>{{v.paymentDate}}</td><td>{{v.reversesId?'−':''}}{{v.amount}}</td><td>{{r(v.method)}}</td><td>{{v.bank||'—'}}</td><td>{{v.reference}}</td><td><RouterLink v-if="!v.reversesId&&!data.payments.some(x=>x.reversesId===v.id)&&scope?.employeeId!==v.employeeId" :to="{path:base+'/payroll-batches/'+id+'/payments/new',query:{employeeId:v.employeeId,reverse:v.id}}">{{r('reversal')}}</RouterLink></td></tr><tr v-if="!data.payments.length"><td colspan="6" class="wf-empty">{{t('empty')}}</td></tr></tbody></table></div></template></section></template>
